export function updateSignalKeyCache() {
  const keys = Array.isArray(state.sim?.probe_keys) ? state.sim.probe_keys : [];
  const rawLabels = (state.sim as unknown as { probe_labels?: Record<string, string> } | null)?.probe_labels;
  const labels: Record<string, string> = rawLabels && typeof rawLabels === 'object' ? rawLabels : {};
  const signature = keys.join('\u0001') + '\u0002' + JSON.stringify(labels);
  if (signature === state.probeSignature) return;
  state.probeSignature = signature;
  state.probeKeys = keys.map((key: string) => labels[key] || key);
  state.probeLabels = labels;

  // 重置后 probe_keys 会短暂为空：保留用户探针选择，避免“重置即清空通道”。
  if (!keys.length) {
    renderSignalList();
    fillInstrumentSelects();
    scheduleChartDraw();
    return;
  }
  // 帧/分析/信号列表统一用显示名，不能退回 raw 稳定键。
  const available = new Set(state.probeKeys);
  for (const key of Array.from(state.chart.selected)) {
    if (!available.has(key)) state.chart.selected.delete(key);
  }
  if (state.chart.selected.size === 0) {
    state.probeKeys.slice(0, 2).forEach((key: string) => state.chart.selected.add(key));
  }
  renderSignalList();
  fillInstrumentSelects();
  scheduleChartDraw();
}
export function ingestFrame(frame: FrameItem) {
  if (!frame || !frame.v) return;
  for (const [key, raw] of Object.entries(frame.v)) {
    if (typeof raw !== 'number' || !Number.isFinite(raw)) continue;
    state.values.set(key, raw);
    if (key.startsWith('n:')) {
      const rest = key.slice(2);
      const cut = rest.lastIndexOf(':');
      if (cut > 0) {
        const name = rest.slice(0, cut);
        const field = rest.slice(cut + 1);
        let bucket = state.nodeValues.get(name);
        if (!bucket) {
          bucket = {};
          state.nodeValues.set(name, bucket);
        }
        bucket[field] = raw;
      }
    } else if (key.startsWith('e:')) {
      const rest = key.slice(2);
      const cut = rest.lastIndexOf(':');
      if (cut > 0) {
        const name = rest.slice(0, cut);
        const field = rest.slice(cut + 1);
        let bucket = state.edgeValues.get(name);
        if (!bucket) {
          bucket = {};
          state.edgeValues.set(name, bucket);
        }
        bucket[field] = raw;
      }
    }
  }
}
